namespace ghidra.app.plugin.processors.sleigh;



using generic.jar;
using ghidra.framework;

public class ModuleDefinitionsMap {
	private static Dictionary<string, string> moduleMap;

	public static Map<string, string> getModuleMap() {
		if (moduleMap == null) {
			Collection<ResourceFile> moduleRootDirectories = Application.getModuleRootDirectories();
			moduleMap = new Dictionary<string, string>();
			foreach (ResourceFile resourceFile in moduleRootDirectories) {
				moduleMap.put(resourceFile.getName(), resourceFile.getAbsolutePath());
			}
		}
		return Collections.unmodifiableMap(moduleMap);
	}
}
